-- World Food Programme via HDX, CC BY-IGO — https://data.humdata.org/dataset/wfp-food-prices-for-cambodia
-- Subset: Every market and every observation dated >= 2020-01-01 and < 2022-01-01. Commodity defaults come from the first retained source observation per commodity ID. Price ID is generated on import.
-- Mapping: Market names and coordinates come from the market register. The price and usdprice fields become price_khr and price_usd; priceflag and pricetype become price_flag and price_type.
-- SHA-256 wfp_markets_khm.csv: a74a766a37ace28459f782f763c914706b61cb81ea6f09c48d71730d10aaa090 (local snapshot mtime 2026-11-20T14:47:36+00:00)
-- SHA-256 wfp_food_prices_khm.csv: 71ddf4e8c555665625e0c875ed3dc9a4378f8ad2fc834a8668c669a5994eb371 (local snapshot mtime 2026-11-20T14:47:34+00:00)
DROP DATABASE IF EXISTS w04_food_prices;
CREATE DATABASE w04_food_prices CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE w04_food_prices;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET @practice_saved_autocommit = @@autocommit;
SET autocommit = 0;

CREATE TABLE market (
    market_id INT PRIMARY KEY,
    market_name VARCHAR(150) NOT NULL,
    province_name VARCHAR(100),
    district_name VARCHAR(100),
    latitude DECIMAL(9,6),
    longitude DECIMAL(9,6)
);


CREATE TABLE commodity (
    commodity_id INT PRIMARY KEY,
    commodity_name VARCHAR(150) NOT NULL,
    category_name VARCHAR(100),
    default_unit VARCHAR(30)
);


CREATE TABLE food_price (
    price_id INT AUTO_INCREMENT PRIMARY KEY,
    price_date DATE NOT NULL,
    market_id INT NOT NULL,
    commodity_id INT NOT NULL,
    unit VARCHAR(30),
    price_flag VARCHAR(30),
    price_type VARCHAR(30),
    currency CHAR(3),
    price_khr DECIMAL(12,2),
    price_usd DECIMAL(10,4),
    FOREIGN KEY (market_id) REFERENCES market(market_id),
    FOREIGN KEY (commodity_id) REFERENCES commodity(commodity_id)
);






































































































COMMIT;
SET autocommit = @practice_saved_autocommit;
SET FOREIGN_KEY_CHECKS = 1;
